export default async function ({ rows, configRows, previous, acknowledge, resolution }, context) {
  const pending = await context.state.get("blog-pending");
  if (pending) {
    if (acknowledge !== String(pending.rowNumber) || !["published", "retry"].includes(resolution))
      throw Error(
        `Publication pending for row ${pending.rowNumber}; inspect WordPress and resolve before continuing`,
      );
    if (resolution === "published")
      throw Error(
        "Mark the corresponding Schedule row Status as publish, then use retry to clear pending",
      );
    await context.state.set("blog-pending", null);
  }
  const index = (previous?.index ?? -1) + 1,
    more = index < rows.length - 1;
  if (!more)
    return {
      state: { index },
      more: false,
      act: false,
      publish: false,
      row: {},
      prompt: "",
      model: "",
      title: "",
      content: "",
      rowNumber: 0,
    };
  const headers = rows[0],
    cells = rows[index + 1],
    row = Object.fromEntries(headers.map((h, i) => [String(h), cells[i] ?? ""]));
  const cfg = Object.fromEntries(configRows.slice(1).map((r) => [String(r[0]), r[1] ?? ""]));
  const act = !!row.Action && row.Action !== row.Status,
    publish = row.Action === "publish";
  if (publish && act) {
    const t = Date.parse(String(row.Scheduled).replace(" ", "T") + "Z");
    if (!Number.isFinite(t)) throw Error("Invalid scheduled timestamp for row " + (index + 2));
    if (t > Date.now())
      return {
        state: { index },
        more: true,
        act: false,
        publish,
        row,
        prompt: "",
        model: "",
        title: "",
        content: "",
        rowNumber: index + 2,
      };
  }
  const replace = (s) =>
    typeof s === "string"
      ? s
          .replace(/\{\{\s*([^}]+)\s*\}\}/g, (_m, p) => {
            p = p.trim();
            return row[p] || cfg[p] || cfg[p + (row.Context || "")] || `[could not find "${p}]"`;
          })
          .trim()
      : "";
  const key = "prompt_" + row.Action,
    prompt = replace(cfg[key]),
    model = replace(cfg[key + "_model"]);
  return {
    state: { index },
    more: true,
    act: act && (publish || !!prompt),
    publish,
    row,
    prompt,
    model,
    title: String(row.Title || ""),
    content: String(row.final || ""),
    rowNumber: index + 2,
  };
}

