export default function ({ rows, row, rowNumber, body, published }) {
  let updated = { ...row };
  if (published) {
    updated.Status = "publish";
  } else {
    const text = body?.choices?.[0]?.message?.content;
    if (typeof text !== "string") throw Error("Model returned no content");
    let gen;
    try {
      gen = JSON.parse(text);
    } catch {
      gen = { Fulltext: text };
    }
    if (!gen || typeof gen !== "object" || Array.isArray(gen)) gen = { Fulltext: text };
    const full = Object.hasOwn(gen, "Fulltext") ? gen.Fulltext : gen;
    gen[row.Action] = full;
    for (const [k, v] of Object.entries(gen)) {
      const a = String(row[k] ?? ""),
        b = typeof v === "object" ? JSON.stringify(v) : String(v);
      updated[k] = a && b ? a + "\n---\n" + b : a || b;
    }
    updated.Status = row.Action;
  }
  const headers = rows[0];
  let n = headers.length,
    col = "";
  while (n) {
    n--;
    col = String.fromCharCode(65 + (n % 26)) + col;
    n = Math.floor(n / 26);
  }
  return {
    range: `'Schedule'!A${rowNumber}:${col}${rowNumber}`,
    values: [headers.map((h) => updated[h] ?? "")],
    log: [
      [
        new Date().toISOString(),
        "info",
        `${published ? "Published" : "Status " + row.Action} row ${rowNumber}`,
      ],
    ],
  };
}

